#!/bin/bash
#
#  PASS 2 -- the citable table.  FIVE variants, FOUR candidate oracles, one
#  frozen generator and one frozen scorer for every variant (pass 1 was
#  generated by two versions of the generator; base was provably unaffected,
#  because its path is a straight copy and its md5 matched SEC, but a table
#  worth citing runs on ONE instrument).
set -u
H=/mnt/c/Users/User00/AppData/Local/Temp/claude/C--DocumentNoSnc-cc-GXEMUL/8e474f41-4d47-4c99-bf11-3406a84c4fcd/scratchpad/o500r
SEC=/mnt/c/DocumentNoSnc/cc/GXEMUL/GXEMUL-SEC
PRISTINE=$SEC/src/devices/dev_sgi_re.c
CLONE=/tmp/gx500r
OUT=$H/outb
mkdir -p $OUT $CLONE/dry
cd $CLONE

echo "TABLE500B start $(date +%H:%M:%S)"
echo "BASELINE NAMED: HEAD $(cd $SEC && git rev-parse --short HEAD)"
echo "  dev_sgi_re.c          md5 $(md5sum $PRISTINE | cut -d' ' -f1)"
echo "  sgi_re_width_probe.py md5 $(md5sum $SEC/regress/sgi_re_width_probe.py | cut -d' ' -f1)"
echo "  mk500.run.py          md5 $(md5sum $H/mk500.run.py | cut -d' ' -f1)"
echo "  score500b.run.py      md5 $(md5sum $H/score500b.run.py | cut -d' ' -f1)"
echo "  clone source cmp vs SEC before mutant 1: $(cmp -s $CLONE/src/devices/dev_sgi_re.c $PRISTINE && echo CLEAN || echo DIFFERS)"
echo ""
python3 $H/mk500.run.py base $PRISTINE $CLONE/dry/base.c >/dev/null 2>&1
python3 $H/mk500.run.py fix  $PRISTINE $CLONE/dry/fix.c  >/dev/null 2>&1

for V in base fix mexit0 mret0 mrdexit0; do
  echo "==================================================================="
  echo "VARIANT: $V   $(date +%H:%M:%S)"
  echo "$V applied to $CLONE/src/devices/dev_sgi_re.c" > $CLONE/.MUTANT
  python3 $H/mk500.run.py $V $PRISTINE $CLONE/src/devices/dev_sgi_re.c
  if [ $? -ne 0 ]; then echo "  VARIANT GEN FAILED -- ABORT"; exit 1; fi
  echo "  source md5: $(md5sum $CLONE/src/devices/dev_sgi_re.c | cut -d' ' -f1)"
  #  MUTANT-NOT-MIS-BUILT CONTROL.  A mutant identical to what it mutates is
  #  not a mutant; it escapes every oracle and reports as a clean generation.
  NB=$(diff -u $CLONE/dry/base.c $CLONE/src/devices/dev_sgi_re.c | grep -cE '^[+-][^+-]')
  NF=$(diff -u $CLONE/dry/fix.c  $CLONE/src/devices/dev_sgi_re.c | grep -cE '^[+-][^+-]')
  echo "  changed lines vs base = $NB   vs fix = $NF"
  case $V in
    base)  [ "$NB" -eq 0 ] || { echo "  base DIFFERS FROM BASE -- ABORT"; exit 1; } ;;
    fix)   [ "$NF" -eq 0 ] || { echo "  fix DIFFERS FROM fix -- ABORT"; exit 1; }
           [ "$NB" -gt 0 ] || { echo "  fix IS IDENTICAL TO BASE -- ABORT"; exit 1; } ;;
    *)     [ "$NF" -gt 0 ] || { echo "  *** MUTANT $V IS IDENTICAL TO fix -- MIS-BUILT, ABORT ***"; exit 1; } ;;
  esac
  echo "  edit vs fix:"
  diff -u $CLONE/dry/fix.c $CLONE/src/devices/dev_sgi_re.c | grep -E '^[+-][^+-]' | sed 's/^/    /'
  rm -f $CLONE/src/devices/dev_sgi_re.o
  make -j8 > /tmp/gx500rb_$V.log 2>&1
  if [ ! -f $CLONE/gxemul ]; then echo "  NO BINARY -- ABORT"; tail -20 /tmp/gx500rb_$V.log; exit 1; fi
  if [ $CLONE/gxemul -nt $CLONE/src/devices/dev_sgi_re.c ]; then
    echo "  build: FRESH ([ binary -nt source ] = YES)"
  else
    echo "  build: STALE -- ABORT"; tail -20 /tmp/gx500rb_$V.log; exit 1
  fi
  cp $CLONE/gxemul $CLONE/gxb.$V

  python3 -u $H/score500b.run.py $CLONE/gxb.$V $V > $OUT/o_$V.txt 2>&1
  RC=$?; ND=$(grep -c '^SCORE500B_DONE$' $OUT/o_$V.txt)
  echo "  ORACLE_RC=$RC  SENTINELS=$ND"
  if [ "$RC" -ne 0 ] || [ "$ND" -ne 1 ]; then
    echo "  *** ORACLE RUN DID NOT COMPLETE -- NOT SCORED, ABORTING ***"
    tail -15 $OUT/o_$V.txt | sed 's/^/    /'; exit 1
  fi
  sed -n '3,$p' $OUT/o_$V.txt | sed 's/^/  /'

  #  THE ROUND'S OWN NEW DETECTOR, unmodified.  This is where the read-direction
  #  and guest-bus-error coverage lives; the shipped 35-row probe has neither.
  python3 -u $H/sgi_re_unmapped_probe.run.py $CLONE/gxb.$V $V > $OUT/u_$V.txt 2>&1
  URC=$?; UND=$(grep -c '^OPUS499T_DONE$' $OUT/u_$V.txt); UNR=$(grep -c '^OPUS499T_RESULT=' $OUT/u_$V.txt)
  echo "  UNMAPPED_PROBE_RC=$URC  SENTINELS=$UND  RESULT_LINES=$UNR"
  if [ "$URC" -ne 0 ] || [ "$UND" -ne 1 ] || [ "$UNR" -ne 1 ]; then
    echo "  *** #499 DETECTOR RUN DID NOT COMPLETE -- NOT SCORED, ABORTING ***"
    tail -12 $OUT/u_$V.txt | sed 's/^/    /'; exit 1
  fi
  grep -E 'FAIL$' $OUT/u_$V.txt | sed 's/^/    /'
  grep -hE '^OPUS499T_(CONTROL|RESULT)' $OUT/u_$V.txt | sed 's/^/    /'
  echo ""
done

echo "==================================================================="
echo "=== RESTORE (two-part clearance) ==="
python3 $H/mk500.run.py base $PRISTINE $CLONE/src/devices/dev_sgi_re.c
rm -f $CLONE/src/devices/dev_sgi_re.o
make -j8 > /tmp/gx500rb_restore.log 2>&1
P1=bad; P2=bad
cmp -s $CLONE/src/devices/dev_sgi_re.c $PRISTINE && { echo "RESTORE part1 cmp vs SEC (never vs my own backup): CLEAN"; P1=ok; } || echo "RESTORE part1: DIFFERS"
if [ $CLONE/gxemul -nt $CLONE/src/devices/dev_sgi_re.c ]; then echo "RESTORE part2 [ binary -nt source ]: YES"; P2=ok; else echo "RESTORE part2: NO"; fi
if [ "$P1" = ok ] && [ "$P2" = ok ]; then rm -f $CLONE/.MUTANT; echo "SENTINEL CLEARED (both parts passed)"; else echo "SENTINEL KEPT ON PURPOSE"; fi
echo ""
echo ""
echo "SENTINEL LEDGER:"
for V in base fix mexit0 mret0 mrdexit0; do
  printf '  %-10s sentinels=%s  verdict_lines=%s\n' "$V" \
    "$(grep -c '^SCORE500B_DONE$' $OUT/o_$V.txt 2>/dev/null)" \
    "$(grep -cE '^  (P|N1|N2|N3) ' $OUT/o_$V.txt 2>/dev/null)"
done
echo "md5 of every pass-2 binary:"; md5sum $CLONE/gxb.* | sort | sed 's/^/  /'
echo "TABLE500B_DONE $(date +%H:%M:%S)"
